INSERT INTO products (category_id, name, description, price, stock_quantity, image_url) VALUES
(1, 'Дриль ударний Bosch 750W', 'Потужний ударний дриль 750 Вт з регулюванням швидкості. Патрон 13мм. Реверс. Підходить для свердління бетону, металу, дерева.', 2850.00, 25, 'https://images.unsplash.com/photo-1504148455328-c376907d081c?w=400&h=300&fit=crop'),
(1, 'Шуруповерт акумуляторний 18V', 'Акумуляторний шуруповерт 18В з Li-Ion батареєю 2.0 Аг. 2 швидкості. Крутний момент 45 Нм. Комплект: зарядний, кейс, 2 акумулятори.', 3200.00, 18, 'https://images.unsplash.com/photo-1572981779307-38b8cabb2407?w=400&h=300&fit=crop'),
(1, 'Болгарка (КШМ) 125мм 1100W', 'Кутова шліфувальна машина 125мм потужністю 1100 Вт. Плавний пуск, регулювання обертів. Для різання металу, каменю, шліфування.', 1750.00, 30, 'https://images.unsplash.com/photo-1426927308491-6380b6a9936f?w=400&h=300&fit=crop'),
(1, 'Лобзик електричний 650W', 'Електролобзик 650 Вт з маятниковим ходом. Глибина різу: дерево 65мм, метал 8мм. Швидкозатискний патрон для пилок.', 1450.00, 22, 'https://images.unsplash.com/photo-1513467535987-fd81bc7d62f8?w=400&h=300&fit=crop'),
(1, 'Рулетка будівельна 5м', 'Професійна рулетка 5 метрів з магнітним зачепом. Ширина полотна 25мм. Прогумований корпус. Автоматичне змотування.', 185.00, 80, 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?w=400&h=300&fit=crop'),
(1, 'Рівень будівельний 80см', 'Алюмінієвий рівень 80см з 3 капсулами. Точність 0.5мм/м. Фрезерована поверхня. Для горизонтальних та вертикальних вимірювань.', 320.00, 45, 'https://images.unsplash.com/photo-1541123603104-512919d6a96c?w=400&h=300&fit=crop'),
(1, 'Набір біт та свердл 100шт', 'Універсальний набір із 100 предметів: біти PH, PZ, TORX, свердла по металу, дереву, бетону. У зручному пластиковому кейсі.', 680.00, 35, 'https://images.unsplash.com/photo-1580901368919-7738efb0f228?w=400&h=300&fit=crop'),
(1, 'Ножівка по дереву 450мм', 'Ручна ножівка з загартованим зубом. Довжина полотна 450мм, 7 зубів/дюйм. Ергономічна двокомпонентна ручка.', 275.00, 55, 'https://images.unsplash.com/photo-1504639725590-34d0984388bd?w=400&h=300&fit=crop'),
(1, 'Перфоратор SDS-plus 800W', 'Перфоратор 800 Вт з патроном SDS-plus. 3 режими роботи: свердління, удар+свердління, довбання. Енергія удару 2.5 Дж.', 3450.00, 15, 'https://images.unsplash.com/photo-1562259929-b4e1fd3aef09?w=400&h=300&fit=crop'),
(1, 'Ключі гайкові набір 12шт', 'Набір комбінованих гайкових ключів 6-22мм, 12 штук. Хром-ванадієва сталь. Матове хромування. В чохлі-скрутці.', 520.00, 40, 'https://images.unsplash.com/photo-1581244277943-fe4a9c777189?w=400&h=300&fit=crop');
INSERT INTO products (category_id, name, description, price, stock_quantity, image_url) VALUES
(2, 'Клей для плитки Ceresit CM 11', 'Клейова суміш для облицювання керамічною плиткою. Мішок 25 кг. Для внутрішніх та зовнішніх робіт. Морозостійкий.', 245.00, 120, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(2, 'Штукатурка гіпсова 30кг', 'Гіпсова штукатурка для внутрішніх робіт. Мішок 30 кг. Ручне та машинне нанесення. Шар від 5 до 50мм.', 195.00, 90, 'https://images.unsplash.com/photo-1607472586893-edb57bdc0e39?w=400&h=300&fit=crop'),
(2, 'Шпаклівка фінішна 20кг', 'Полімерна фінішна шпаклівка для стін та стель. 20 кг. Білосніжна. Легке шліфування. Шар 0.2-3мм.', 280.00, 65, 'https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=400&h=300&fit=crop'),
(2, 'Грунтовка глибокого проникнення 10л', 'Акрилова грунтовка для мінеральних основ. Каністра 10л. Зміцнює поверхню, знижує водопоглинання. Витрата 100-200 мл/м².', 310.00, 50, 'https://images.unsplash.com/photo-1562259949-e8e7689d7828?w=400&h=300&fit=crop'),
(2, 'Цегла червона рядова М-100', 'Керамічна будівельна цегла М-100. Розмір 250x120x65мм. Морозостійкість F50. Ціна за 1 штуку. Мінімальне замовлення 100шт.', 12.50, 5000, 'https://images.unsplash.com/photo-1590069261209-f8e9b8642343?w=400&h=300&fit=crop'),
(2, 'Пісок будівельний (мішок 50кг)', 'Промитий річковий пісок. Мішок 50 кг. Фракція 0.5-2мм. Для розчинів, стяжок, підсипки.', 75.00, 200, 'https://images.unsplash.com/photo-1580168644792-a914e15aebfa?w=400&h=300&fit=crop'),
(2, 'Гіпсокартон стіновий 12.5мм', 'Гіпсокартонний лист 2500х1200х12.5мм. Для облицювання стін та перегородок. Стандартна кромка УК.', 185.00, 150, 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=400&h=300&fit=crop'),
(2, 'Профіль CD-60 3м', 'Стельовий профіль CD-60 довжиною 3м. Товщина металу 0.5мм. Оцинкований. Для каркасів під гіпсокартон.', 68.00, 300, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(2, 'Сітка штукатурна 160г/м²', 'Фасадна склосітка 160 г/м², рулон 50м². Лугостійка. Для армування штукатурних шарів. Комірка 5х5мм.', 420.00, 40, 'https://images.unsplash.com/photo-1587293852726-70cdb56c2866?w=400&h=300&fit=crop'),
(2, 'Утеплювач пінопласт 100мм', 'Пінополістирол ПСБ-С 25, товщина 100мм. Лист 1000х500мм. Щільність 25 кг/м³. Для утеплення фасадів.', 95.00, 500, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop');
INSERT INTO products (category_id, name, description, price, stock_quantity, image_url) VALUES
(3, 'Розетка подвійна з заземленням', 'Подвійна розетка з заземлюючим контактом. Білий колір. Скрита проводка. Номінальний струм 16А, 250В.', 125.00, 200, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Вимикач двоклавішний білий', 'Вимикач на 2 клавіші для скритої проводки. Білий. Номінальний струм 10А. Пружинні клеми для швидкого монтажу.', 85.00, 180, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Автомат захисту 16А однополюсний', 'Автоматичний вимикач 16А, 1P, характеристика C. Відключаюча здатність 4.5кА. DIN-рейка. Для захисту розеткових груп.', 95.00, 150, 'https://images.unsplash.com/photo-1555664424-778a1e5e1b48?w=400&h=300&fit=crop'),
(3, 'Кабель-канал 40х25мм 2м', 'Пластиковий кабель-канал 40х25мм, довжина 2м. Білий. З кришкою на засувках. Для відкритої проводки.', 48.00, 250, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Щиток розподільчий на 12 модулів', 'Навісний щиток на 12 модулів з прозорою дверцятою. IP40. DIN-рейка та шини N/PE в комплекті.', 380.00, 35, 'https://images.unsplash.com/photo-1555664424-778a1e5e1b48?w=400&h=300&fit=crop'),
(3, 'Гофра ПВХ 20мм (50м)', 'Гофрована труба ПВХ діаметром 20мм. Бухта 50 метрів. З протяжкою. Для прокладки кабелів у стінах та стелях.', 220.00, 60, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Лампа LED 12W E27 4000K', 'Світлодіодна лампа 12 Вт, цоколь E27. Нейтральне біле світло 4000K. 1080 лм. Термін служби 30000 годин.', 65.00, 300, 'https://images.unsplash.com/photo-1565849904461-04a58ad377e0?w=400&h=300&fit=crop'),
(3, 'Подовжувач 5м на 3 розетки', 'Мережевий подовжувач 5 метрів, 3 розетки з заземленням. Перетин 1.5мм². Максимальне навантаження 3500 Вт.', 320.00, 45, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Ізострічка ПВХ 19мм (20м)', 'Ізоляційна стрічка ПВХ 19мм х 20м. Чорна. Робоча температура від -10 до +80°C. Напруга пробою 6000В.', 28.00, 400, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(3, 'Кабель NYM 3х1.5 (50м)', 'Кабель NYM-J 3x1.5мм², бухта 50 метрів. Мідні жили. Потрійна ізоляція. Для внутрішньої стаціонарної проводки.', 1850.00, 20, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop');
INSERT INTO products (category_id, name, description, price, stock_quantity, image_url) VALUES
(4, 'Змішувач для кухні хром', 'Одноважільний кухонний змішувач з поворотним виливом. Хромоване покриття. Картридж 40мм. Гнучкі підводки в комплекті.', 980.00, 30, 'https://images.unsplash.com/photo-1585704032915-c3400ca199e7?w=400&h=300&fit=crop'),
(4, 'Змішувач для ванни з душем', 'Настінний змішувач для ванни з душовою лійкою та шлангом 1.5м. Хром. Керамічний картридж. Перемикач на корпусі.', 1350.00, 22, 'https://images.unsplash.com/photo-1584622650111-993a426fbf0a?w=400&h=300&fit=crop'),
(4, 'Унітаз компакт з бачком', 'Унітаз-компакт з нижнім підведенням. Подвійний змив 3/6л. Антибактеріальне сидіння soft-close в комплекті.', 3200.00, 12, 'https://images.unsplash.com/photo-1585412727339-54e4bae3bbf9?w=400&h=300&fit=crop'),
(4, 'Раковина 60см підвісна біла', 'Керамічна підвісна раковина 60 см. Білий колір. З отвором під змішувач та переливом. Кріплення в комплекті.', 1150.00, 18, 'https://images.unsplash.com/photo-1552321554-5fefe8c9ef14?w=400&h=300&fit=crop'),
(4, 'Труба поліпропіленова 25мм (4м)', 'ПП труба для гарячого та холодного водопостачання, d=25мм, 4 метри. Армована скловолокном. Тиск до 25 бар.', 120.00, 100, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(4, 'Сифон для раковини хром', 'Пляшковий сифон для раковини 1.1/4" з випуском. Хромований. Висота регулюється. Легке обслуговування.', 210.00, 50, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(4, 'Ванна акрилова 170х70', 'Акрилова прямокутна ванна 170х70 см. Товщина акрилу 4мм. Каркас та ніжки в комплекті. Об''єм 200л.', 4500.00, 8, 'https://images.unsplash.com/photo-1507652313519-d4e9174996dd?w=400&h=300&fit=crop'),
(4, 'Водонагрівач 50л електричний', 'Накопичувальний водонагрівач 50 літрів. Потужність 1.5 кВт. Нержавіючий бак. Захист від перегріву та сухого ввімкнення.', 3800.00, 10, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(4, 'Лічильник води холодної', 'Лічильник холодної води крильчастий DN15. Точність ±2%. Сертифікований. Міжповірочний інтервал 4 роки.', 350.00, 60, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(4, 'Гнучка підводка 1/2" 80см', 'Гнучка підводка для води 1/2" довжиною 80 см. Нержавіюча оплетка. Для підключення змішувачів, бачків, бойлерів.', 55.00, 150, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop');
INSERT INTO products (category_id, name, description, price, stock_quantity, image_url) VALUES
(5, 'Фарба інтер''єрна біла 10л', 'Водоемульсійна акрилова фарба для стін та стель. Матова. Білосніжна. Витрата 150 мл/м². Час висихання 2 години.', 850.00, 40, 'https://images.unsplash.com/photo-1562259949-e8e7689d7828?w=400&h=300&fit=crop'),
(5, 'Фарба фасадна атмосферостійка 10л', 'Силіконова фасадна фарба для зовнішніх робіт. 10 літрів. Водовідштовхувальна. Паропроникна. Стійка до UV-променів.', 1250.00, 25, 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?w=400&h=300&fit=crop'),
(5, 'Емаль алкідна ПФ-115 біла 2.8кг', 'Алкідна емаль для дерева та металу. 2.8 кг. Глянцева. Для зовнішніх та внутрішніх робіт. Стійка до атмосферних впливів.', 320.00, 55, 'https://images.unsplash.com/photo-1562259949-e8e7689d7828?w=400&h=300&fit=crop'),
(5, 'Лак паркетний поліуретановий 2.5л', 'Поліуретановий паркетний лак 2.5л. Напівматовий. Зносостійкий. Для підлоги з високим навантаженням. 3 шари.', 780.00, 30, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(5, 'Морилка для дерева горіх 1л', 'Морилка на водній основі, колір горіх. 1 літр. Підкреслює текстуру деревини. Швидке висихання. Без запаху.', 145.00, 70, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(5, 'Антисептик для дерева 5л', 'Захисний антисептик-просочення для дерева. 5 літрів. Від гниття, грибка, комах. Безколірний. Для зовнішніх робіт.', 480.00, 35, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(5, 'Розчинник Уайт-спірит 1л', 'Розчинник для масляних фарб, емалей, лаків. 1 літр. Для розведення та очищення інструменту після фарбування.', 85.00, 100, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(5, 'Валик малярний 250мм + ручка', 'Малярний валик 250мм з поролоновою шубкою та телескопічною ручкою 1.5м. Для фарбування стін та стель.', 195.00, 60, 'https://images.unsplash.com/photo-1562259949-e8e7689d7828?w=400&h=300&fit=crop'),
(5, 'Пензлик набір 5шт (флейці)', 'Набір малярних пензлів: 5 штук (25, 38, 50, 63, 75мм). Натуральна щетина. Дерев''яна ручка. Для фарб та лаків.', 165.00, 80, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop'),
(5, 'Скотч малярний 48мм (50м)', 'Кріпований малярний скотч 48мм х 50м. Жовтий. Для захисту поверхонь при фарбуванні. Легко знімається без слідів.', 65.00, 120, 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=400&h=300&fit=crop');
